use sea_orm::{ActiveValue::Set, EntityTrait};

use super::{config::Config, db, entities::note};

const SEED_CHUNK: u64 = 1_000;

pub async fn seed(count: u64) -> anyhow::Result<()> {
    let config = Config::from_env()?;
    let db = db::connect(&config.database_url).await?;
    let mut inserted = 0;
    while inserted < count {
        let chunk = SEED_CHUNK.min(count - inserted);
        let models = (inserted + 1..=inserted + chunk).map(|n| note::ActiveModel {
            title: Set(format!("Seeded note {n}")),
            body: Set(format!(
                "Generated by the seed command, number {n} of {count}."
            )),
            ..Default::default()
        });
        note::Entity::insert_many(models).exec(&db).await?;
        inserted += chunk;
        println!("Inserted {inserted} of {count}");
    }
    Ok(())
}
